"use client";
import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState, type CSSProperties, type Dispatch, type ReactNode, type SetStateAction } from "react";
import { appearanceStorageKey, presetsStorageKey, defaultAppearance, createAppearance, normalizeAppearance, parseAppearance, resolveAppearance, type AppearanceConfig, type SavedAppearance } from "@/lib/appearance";
import "@/styles/effects.css";

interface AppearanceContextValue {
  appearance: AppearanceConfig;
  setAppearance: Dispatch<SetStateAction<AppearanceConfig>>;
  resetAppearance: () => void;
  presets: SavedAppearance[];
  savePreset: (name: string) => void;
  deletePreset: (id: string) => void;
  applyPreset: (id: string) => void;
  importAppearance: (text: string) => void;
}
const noop = () => {};
const Context = createContext<AppearanceContextValue>({ appearance: defaultAppearance, setAppearance: noop, resetAppearance: noop, presets: [], savePreset: noop, deletePreset: noop, applyPreset: noop, importAppearance: noop });
export function useAppearance() { return useContext(Context); }

export function applyAppearanceToDocument(config: AppearanceConfig) {
  const root = document.documentElement;
  root.classList.toggle("dark", config.theme === "dark");
  root.style.colorScheme = config.theme;
  root.dataset.palette = config.palette;
  root.dataset.material = config.material;
  root.dataset.motionLevel = config.motion;
  root.dataset.hoverEffect = config.hover;
  root.dataset.density = config.density;
  root.dataset.typography = config.typography;
  for (const [name, value] of Object.entries(resolveAppearance(config))) root.style.setProperty(name, value);
  window.dispatchEvent(new CustomEvent("aureform:appearance-change", { detail: config }));
}
function loadAppearance(): AppearanceConfig {
  try {
    const raw = localStorage.getItem(appearanceStorageKey);
    if (raw) return parseAppearance(raw);
    const legacy = localStorage.getItem("aureform:theme");
    return createAppearance("aurora", legacy === "light" ? "light" : "dark");
  } catch { return createAppearance(); }
}
function loadPresets(): SavedAppearance[] {
  try {
    const input: unknown = JSON.parse(localStorage.getItem(presetsStorageKey) || "[]");
    if (!Array.isArray(input)) return [];
    return input.slice(0, 100).flatMap((item) => {
      try {
        if (typeof item?.id !== "string" || typeof item?.name !== "string") return [];
        return [{ id: item.id.slice(0, 80), name: item.name.slice(0, 80), config: normalizeAppearance(item.config) }];
      } catch { return []; }
    });
  } catch { return []; }
}
export function AppearanceProvider({ children, initialAppearance = defaultAppearance, applyToDocument = true }: {
  children: ReactNode; initialAppearance?: AppearanceConfig; applyToDocument?: boolean;
}) {
  const [appearance, setState] = useState<AppearanceConfig>(initialAppearance);
  const [initialProps, setInitialProps] = useState({ initialAppearance, applyToDocument });
  const [presets, setPresets] = useState<SavedAppearance[]>([]);
  const appearanceRef = useRef(initialAppearance);
  const presetsRef = useRef<SavedAppearance[]>([]);
  // A controlled scope must expose new props before its children commit.
  // Adjusting this provider's state during its own render avoids a second,
  // passive state update for every color or range input in the Studio.
  if (initialProps.initialAppearance !== initialAppearance || initialProps.applyToDocument !== applyToDocument) {
    setInitialProps({ initialAppearance, applyToDocument });
    if (!applyToDocument) setState(initialAppearance);
  }
  useEffect(() => {
    if (!applyToDocument) return;
    const hydrate = () => {
      const next = loadAppearance();
      appearanceRef.current = next;
      setState(next);
      const saved = loadPresets();
      presetsRef.current = saved;
      setPresets(saved);
      applyAppearanceToDocument(next);
    };
    hydrate();
    const onStorage = (event: StorageEvent) => {
      if (event.key === appearanceStorageKey || event.key === presetsStorageKey || event.key === "aureform:theme") hydrate();
    };
    window.addEventListener("storage", onStorage);
    return () => window.removeEventListener("storage", onStorage);
  }, [applyToDocument]);
  useEffect(() => {
    if (!applyToDocument) {
      appearanceRef.current = initialAppearance;
    }
  }, [initialAppearance, applyToDocument]);
  const setAppearance = useCallback<Dispatch<SetStateAction<AppearanceConfig>>>((update) => {
    const next = normalizeAppearance(typeof update === "function" ? update(appearanceRef.current) : update);
    appearanceRef.current = next;
    setState(next);
    if (applyToDocument) {
      applyAppearanceToDocument(next);
      try {
        const serialized = JSON.stringify(next);
        localStorage.setItem(appearanceStorageKey, serialized);
        localStorage.setItem("aureform:appearance-paint:v1", JSON.stringify({ config: serialized, variables: resolveAppearance(next) }));
        localStorage.setItem("aureform:theme", next.theme);
      } catch { /* A blocked storage leaves the current appearance usable. */ }
    }
  }, [applyToDocument]);
  const updatePresets = useCallback((update: (previous: SavedAppearance[]) => SavedAppearance[]) => {
    const next = update(presetsRef.current);
    presetsRef.current = next;
    setPresets(next);
    if (applyToDocument) { try { localStorage.setItem(presetsStorageKey, JSON.stringify(next)); } catch {} }
  }, [applyToDocument]);
  const resetAppearance = useCallback(() => setAppearance(createAppearance()), [setAppearance]);
  const savePreset = useCallback((name: string) => {
    const label = name.trim().slice(0, 80);
    if (!label) throw new Error("Give your preset a name.");
    updatePresets((previous) => [...previous.slice(-99), { id: crypto.randomUUID(), name: label, config: normalizeAppearance(appearance) }]);
  }, [appearance, updatePresets]);
  const deletePreset = useCallback((id: string) => updatePresets((previous) => previous.filter((p) => p.id !== id)), [updatePresets]);
  const applyPreset = useCallback((id: string) => { const preset = presets.find((p) => p.id === id); if (preset) setAppearance(preset.config); }, [presets, setAppearance]);
  const importAppearance = useCallback((text: string) => setAppearance(parseAppearance(text)), [setAppearance]);
  const value = useMemo(() => ({ appearance, setAppearance, resetAppearance, presets, savePreset, deletePreset, applyPreset, importAppearance }), [appearance, setAppearance, resetAppearance, presets, savePreset, deletePreset, applyPreset, importAppearance]);
  return <Context.Provider value={value}>{children}</Context.Provider>;
}
export function AppearanceScope({ appearance, children, className = "" }: { appearance: AppearanceConfig; children: ReactNode; className?: string }) {
  const normalized = useMemo(() => normalizeAppearance(appearance), [appearance]);
  return (
    <AppearanceProvider initialAppearance={normalized} applyToDocument={false}>
      <div className={`af-appearance-scope ${normalized.theme === "dark" ? "dark" : ""} ${className}`}
        data-palette={normalized.palette} data-material={normalized.material} data-motion-level={normalized.motion}
        data-hover-effect={normalized.hover} data-density={normalized.density} data-typography={normalized.typography}
        style={{ ...resolveAppearance(normalized), colorScheme: normalized.theme } as CSSProperties}>
        {children}
      </div>
    </AppearanceProvider>
  );
}

import type { ComponentProps } from "react";
import { cn } from "@/lib/utils";
export function AureformMark({ className, ...props }: ComponentProps<"svg">) {
  return (
    <svg
      viewBox="0 0 32 32"
      fill="currentColor"
      aria-hidden="true"
      className={cn("size-7", className)}
      {...props}
    >
      <path d="M4 28 14 4h5L9 28H4Z M21 12l7 16h-5l-5-11 3-5Z M11 21h8l2 4H9l2-4Z" />
    </svg>
  );
}
export function Brand({
  compact = false,
  className,
}: {
  compact?: boolean;
  className?: string;
}) {
  return (
    <span
      className={cn(
        "inline-flex items-center gap-2.5 text-foreground",
        className,
      )}
    >
      <AureformMark className="size-7 text-primary" />
      {!compact && (
        <span className="text-[21px] font-semibold tracking-[-0.8px]">
          aureform
          {" "}
          <span className="ml-1 text-xs font-normal tracking-normal text-muted-foreground">
            ui
          </span>
        </span>
      )}
    </span>
  );
}

"use client";

import { useEffect, type RefObject } from "react";
import { effectFrameInterval } from "./effect-utils";

export type EffectEnvironment = {
  inView: boolean;
  visible: boolean;
  motion: boolean;
  finePointer: boolean;
};

/** Browser APIs are touched only by effects, never during an SSR render. */
export function watchEffectEnvironment(
  element: HTMLElement,
  notify: (environment: EffectEnvironment) => void,
) {
  const reduced =
    typeof window.matchMedia === "function"
      ? window.matchMedia("(prefers-reduced-motion: reduce)")
      : null;
  const pointer =
    typeof window.matchMedia === "function"
      ? window.matchMedia("(hover: hover) and (pointer: fine)")
      : null;
  const forced =
    typeof window.matchMedia === "function"
      ? window.matchMedia("(forced-colors: active)")
      : null;
  let disposed = false;
  let inView = false;

  const visible = () => {
    if (document.visibilityState === "hidden" || !element.isConnected)
      return false;
    const style = getComputedStyle(element);
    // checkVisibility checks the host box, but its own hidden content can still
    // leave that box visible while suppressing every decorative child.
    if (
      style.visibility === "hidden" ||
      style.visibility === "collapse" ||
      style.opacity === "0" ||
      style.contentVisibility === "hidden"
    )
      return false;
    if (typeof element.checkVisibility === "function") {
      return element.checkVisibility({
        checkOpacity: true,
        checkVisibilityCSS: true,
        contentVisibilityAuto: true,
      });
    }
    if (!element.getClientRects().length) return false;
    for (
      let ancestor: HTMLElement | null = element;
      ancestor;
      ancestor = ancestor.parentElement
    ) {
      const ancestorStyle = getComputedStyle(ancestor);
      if (
        ancestorStyle.opacity === "0" ||
        ancestorStyle.contentVisibility === "hidden"
      )
        return false;
    }
    return true;
  };

  const report = () => {
    if (disposed) return;
    notify({
      inView,
      visible: visible(),
      motion:
        reduced !== null &&
        !reduced.matches &&
        !forced?.matches &&
        (
          element.closest("[data-motion-level]") ?? document.documentElement
        ).getAttribute("data-motion-level") !== "off",
      finePointer: pointer?.matches ?? false,
    });
  };

  const observeMedia = (media: MediaQueryList | null) => {
    if (!media) return () => {};
    if (typeof media.addEventListener === "function") {
      media.addEventListener("change", report);
      return () => media.removeEventListener("change", report);
    }
    media.addListener(report);
    return () => media.removeListener(report);
  };
  const removeReduced = observeMedia(reduced);
  const removePointer = observeMedia(pointer);
  const removeForced = observeMedia(forced);
  document.addEventListener("visibilitychange", report);
  window.addEventListener("aureform:appearance-change", report);
  window.addEventListener("resize", report, { passive: true });

  // Observe only this element's ancestry, not every mutation in the document.
  // Ignore our own pointer variables, which otherwise retrigger the observer.
  const ownStyle = () =>
    Array.from(element.style)
      .filter((name) => !name.startsWith("--afx-"))
      .map(
        (name) =>
          `${name}:${element.style.getPropertyValue(name)}:${element.style.getPropertyPriority(name)}`,
      )
      .join(";");
  let previousStyle = ownStyle();
  const motionObserver =
    typeof MutationObserver !== "undefined"
      ? new MutationObserver((records) => {
          const nextStyle = ownStyle();
          const ownVariablesOnly =
            nextStyle === previousStyle &&
            records.every(
              (record) =>
                record.target === element && record.attributeName === "style",
            );
          previousStyle = nextStyle;
          if (!ownVariablesOnly) report();
        })
      : null;
  for (
    let ancestor: HTMLElement | null = element;
    ancestor;
    ancestor = ancestor.parentElement
  ) {
    motionObserver?.observe(ancestor, {
      attributes: true,
      attributeFilter: [
        "data-motion-level",
        "data-palette",
        "style",
        "class",
        "hidden",
        "open",
        "disabled",
      ],
    });
  }

  let intersection: IntersectionObserver | null = null;
  const measureView = () => {
    const bounds = element.getBoundingClientRect();
    inView =
      bounds.width > 0 &&
      bounds.height > 0 &&
      bounds.bottom > 0 &&
      bounds.right > 0 &&
      bounds.top < window.innerHeight &&
      bounds.left < window.innerWidth;
    report();
  };
  if (typeof IntersectionObserver !== "undefined") {
    intersection = new IntersectionObserver(
      ([entry]) => {
        inView = Boolean(entry?.isIntersecting && entry.intersectionRatio > 0);
        report();
      },
      { threshold: 0 },
    );
    intersection.observe(element);
  } else {
    // Old embedded browsers still pause offscreen without a polyfill.
    window.addEventListener("scroll", measureView, {
      passive: true,
      capture: true,
    });
    window.addEventListener("resize", measureView, { passive: true });
    measureView();
  }
  report();

  return () => {
    disposed = true;
    intersection?.disconnect();
    motionObserver?.disconnect();
    removeReduced();
    removePointer();
    removeForced();
    document.removeEventListener("visibilitychange", report);
    window.removeEventListener("aureform:appearance-change", report);
    window.removeEventListener("resize", report);
    window.removeEventListener("scroll", measureView, true);
    window.removeEventListener("resize", measureView);
  };
}

export function useEffectActivity(ref: RefObject<HTMLElement | null>) {
  useEffect(() => {
    const element = ref.current;
    if (!element) return;
    const remove = watchEffectEnvironment(element, (environment) => {
      element.dataset.afxMotion =
        environment.motion && environment.visible && environment.inView
          ? "running"
          : "paused";
    });
    return () => {
      remove();
      element.dataset.afxMotion = "paused";
    };
  }, [ref]);
}

const editingTarget =
  'input, textarea, select, [contenteditable]:not([contenteditable="false"]), [data-effect-static]';
const disabledTarget = ':disabled, [aria-disabled="true"], [data-disabled]';

/**
 * One frame-coalesced write per pointer update. Never captures a pointer,
 * cancels an event, changes touch-action, or installs a wheel handler.
 */
export function useEffectPointer(
  ref: RefObject<HTMLElement | null>,
  mode: "spotlight" | "tilt" | "magnetic",
  amount: number,
  limit: number,
) {
  useEffect(() => {
    const element = ref.current;
    if (!element) return;
    let environment: EffectEnvironment = {
      inView: false,
      visible: false,
      motion: false,
      finePointer: false,
    };
    let frame = 0;
    let lastWrite = -Infinity;
    let bounds: DOMRect | null = null;
    let point = { x: 0, y: 0 };

    const reset = () => {
      if (frame) cancelAnimationFrame(frame);
      frame = 0;
      bounds = null;
      element.dataset.afxPointer = "idle";
      element.style.setProperty("--afx-pointer-x", "50%");
      element.style.setProperty("--afx-pointer-y", "35%");
      element.style.setProperty("--afx-rotate-x", "0deg");
      element.style.setProperty("--afx-rotate-y", "0deg");
      element.style.setProperty("--afx-magnetic-x", "0px");
      element.style.setProperty("--afx-magnetic-y", "0px");
    };

    const allowed = () =>
      environment.inView &&
      environment.visible &&
      environment.motion &&
      environment.finePointer &&
      !element.matches(disabledTarget) &&
      // Keep a focused control stationary for keyboard and mixed-input users.
      (mode === "spotlight" || !element.contains(document.activeElement));

    const write = (now: number) => {
      frame = 0;
      if (!allowed() || !bounds || !bounds.width || !bounds.height) {
        reset();
        return;
      }
      if (now - lastWrite < effectFrameInterval) {
        frame = requestAnimationFrame(write);
        return;
      }
      lastWrite = now;
      const x = Math.min(
        1,
        Math.max(0, (point.x - bounds.left) / bounds.width),
      );
      const y = Math.min(
        1,
        Math.max(0, (point.y - bounds.top) / bounds.height),
      );
      element.dataset.afxPointer = "active";
      element.style.setProperty("--afx-pointer-x", `${(x * 100).toFixed(2)}%`);
      element.style.setProperty("--afx-pointer-y", `${(y * 100).toFixed(2)}%`);
      if (mode === "tilt") {
        element.style.setProperty(
          "--afx-rotate-x",
          `${((0.5 - y) * amount * 2).toFixed(2)}deg`,
        );
        element.style.setProperty(
          "--afx-rotate-y",
          `${((x - 0.5) * amount * 2).toFixed(2)}deg`,
        );
      } else if (mode === "magnetic") {
        const dx = Math.min(
          limit,
          Math.max(-limit, (x - 0.5) * bounds.width * amount),
        );
        const dy = Math.min(
          limit,
          Math.max(-limit, (y - 0.5) * bounds.height * amount),
        );
        element.style.setProperty("--afx-magnetic-x", `${dx.toFixed(2)}px`);
        element.style.setProperty("--afx-magnetic-y", `${dy.toFixed(2)}px`);
      }
    };

    const move = (event: PointerEvent) => {
      if (
        !allowed() ||
        event.defaultPrevented ||
        event.buttons !== 0 ||
        !["mouse", "pen"].includes(event.pointerType) ||
        (event.target instanceof Element && event.target.closest(editingTarget))
      ) {
        reset();
        return;
      }
      // A stable entry rectangle prevents feedback from the element's transform.
      bounds ??= element.getBoundingClientRect();
      point = { x: event.clientX, y: event.clientY };
      if (!frame) frame = requestAnimationFrame(write);
    };
    const focus = () => reset();
    const removeEnvironment = watchEffectEnvironment(element, (next) => {
      environment = next;
      element.dataset.afxMotion =
        next.motion && next.inView && next.visible ? "running" : "paused";
      if (!allowed()) reset();
    });

    element.addEventListener("pointerenter", move, { passive: true });
    element.addEventListener("pointermove", move, { passive: true });
    element.addEventListener("pointerleave", reset, { passive: true });
    element.addEventListener("pointercancel", reset, { passive: true });
    element.addEventListener("pointerdown", reset, { passive: true });
    element.addEventListener("focusin", focus);
    window.addEventListener("scroll", reset, { passive: true, capture: true });
    window.addEventListener("resize", reset, { passive: true });

    // Native disabled/loading changes also settle an already active transform.
    const disabledObserver =
      typeof MutationObserver !== "undefined"
        ? new MutationObserver(() => {
            if (element.matches(disabledTarget)) reset();
          })
        : null;
    disabledObserver?.observe(element, {
      attributes: true,
      attributeFilter: ["disabled", "aria-disabled", "data-disabled"],
    });

    return () => {
      removeEnvironment();
      disabledObserver?.disconnect();
      element.removeEventListener("pointerenter", move);
      element.removeEventListener("pointermove", move);
      element.removeEventListener("pointerleave", reset);
      element.removeEventListener("pointercancel", reset);
      element.removeEventListener("pointerdown", reset);
      element.removeEventListener("focusin", focus);
      window.removeEventListener("scroll", reset, true);
      window.removeEventListener("resize", reset);
      reset();
      element.dataset.afxMotion = "paused";
    };
  }, [ref, mode, amount, limit]);
}

"use client";

import {
  Children,
  Fragment,
  cloneElement,
  createElement,
  isValidElement,
  useCallback,
  type HTMLAttributes,
  type ReactElement,
  type ReactNode,
  type Ref,
} from "react";
import { cn } from "@/lib/utils";

export type EffectSurfaceProps = HTMLAttributes<HTMLElement> & {
  as?: "div" | "article" | "section";
  /** Apply the effect to one ref-forwarding element, such as an a or button. */
  asChild?: boolean;
  children?: ReactNode;
  ref?: Ref<HTMLElement>;
};

type SurfaceElementProps = HTMLAttributes<HTMLElement> & {
  ref?: Ref<HTMLElement>;
};

export function useComposedEffectRef(
  outerRef?: Ref<HTMLElement>,
  innerRef?: Ref<HTMLElement>,
) {
  return useCallback(
    (node: HTMLElement | null) => {
      const refs = [outerRef, innerRef];
      const cleanups = refs.map((ref) => {
        if (typeof ref === "function") return ref(node);
        if (ref) ref.current = node;
      });
      return () => {
        refs.forEach((ref, index) => {
          const cleanup = cleanups[index];
          if (typeof cleanup === "function") cleanup();
          else if (typeof ref === "function") ref(null);
          else if (ref) ref.current = null;
        });
      };
    },
    [outerRef, innerRef],
  );
}

/**
 * Preserve the child's semantics, handlers and ref. Cards do not acquire a
 * tab stop or a button role simply because they have a decorative effect.
 */
export function EffectSurface({
  as = "div",
  asChild = false,
  children,
  ref,
  ...props
}: Omit<EffectSurfaceProps, "as"> & {
  as?: EffectSurfaceProps["as"] | "button";
  type?: "button" | "submit" | "reset";
  disabled?: boolean;
}) {
  const child = asChild ? Children.only(children) : null;
  if (asChild && (!isValidElement(child) || child.type === Fragment)) {
    throw new Error("An effect with asChild needs one ref-forwarding element.");
  }

  const element = child as ReactElement<SurfaceElementProps> | null;
  const childRef = element?.props.ref;
  const mergedRef = useComposedEffectRef(ref, childRef);

  if (!element) {
    return createElement(as, { ...props, ref: mergedRef }, children);
  }

  const merged: Record<string, unknown> = { ...props, ...element.props };
  for (const key of Object.keys(props)) {
    const outside = (props as Record<string, unknown>)[key];
    const inside = (element.props as Record<string, unknown>)[key];
    if (
      /^on[A-Z]/.test(key) &&
      typeof outside === "function" &&
      typeof inside === "function"
    ) {
      merged[key] = (event: { defaultPrevented?: boolean }) => {
        inside(event);
        if (!event.defaultPrevented) outside(event);
      };
    }
  }
  merged.className = cn(props.className, element.props.className);
  merged.style = { ...props.style, ...element.props.style };
  merged.ref = mergedRef;
  return cloneElement(element, merged);
}

import type { CSSProperties } from "react";

export const defaultEffectColors = ["#8b5cf6", "#22d3ee", "#34d399"] as const;
export const effectFrameRate = 30;
export const effectFrameInterval = 1000 / effectFrameRate;

export type EffectStyle = CSSProperties & {
  [key: `--afx-${string}`]: string | number;
};

export function boundedNumber(
  value: number | undefined,
  min: number,
  max: number,
  fallback: number,
) {
  return Number.isFinite(value)
    ? Math.min(max, Math.max(min, value as number))
    : fallback;
}

/** Missing palette entries retain the original violet/cyan/emerald palette. */
export function effectColors(colors?: string[]): [string, string, string] {
  return defaultEffectColors.map((fallback, index) => {
    const color = colors?.[index];
    const token = ["primary", "secondary", "tertiary"][index];
    return typeof color === "string" && color.trim()
      ? color.trim()
      : `var(--af-color-${token}, ${fallback})`;
  }) as [string, string, string];
}

export function paletteStyle(colors?: string[]): EffectStyle {
  const [a, b, c] = effectColors(colors);
  return { "--afx-color-a": a, "--afx-color-b": b, "--afx-color-c": c };
}

export type GradientKind = "linear" | "radial" | "mesh";
export type ShaderKind = "aurora" | "waves" | "iridescent" | "none";

export function gradientField(
  kind: GradientKind,
  colors?: string[],
  angle = 135,
) {
  const [a, b, c] = effectColors(colors);
  const degrees = boundedNumber(angle, -3600, 3600, 135);

  if (kind === "linear") {
    return `linear-gradient(${degrees}deg, ${a} 0%, ${b} 52%, ${c} 100%)`;
  }
  if (kind === "radial") {
    return `radial-gradient(ellipse at 72% 28%, ${c} 0%, ${b} 36%, ${a} 72%, #090a16 100%)`;
  }
  return [
    `radial-gradient(ellipse at 82% 18%, ${c} 0%, transparent 46%)`,
    `radial-gradient(ellipse at 68% 78%, ${b} 0%, transparent 55%)`,
    `radial-gradient(ellipse at 15% 24%, ${a} 0%, transparent 62%)`,
    "linear-gradient(135deg, #161027, #090e1d)",
  ].join(", ");
}

/*
 * Colocated, importable mechanics. Every selector is effects-owned; no
 * AppearanceProvider, global effects stylesheet or generated token is needed.
 */
@property --afx-orbit {
  syntax: "<angle>";
  initial-value: 0deg;
  inherits: false;
}

@keyframes afx-border-orbit {
  to {
    --afx-orbit: 360deg;
  }
}

@layer components {
  .afx-background {
    position: relative;
    isolation: isolate;
    overflow: hidden;
    background-color: #090a16;
    color: #f8fafc;
  }

  .afx-background-field,
  .afx-shader-canvas,
  .afx-background-scrim {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    user-select: none;
  }

  .afx-background-field {
    opacity: var(--afx-intensity, 0.55);
  }

  .afx-shader-canvas {
    display: block;
    opacity: 0;
    transition: opacity 400ms ease;
  }

  .afx-shader-canvas[data-ready="true"] {
    opacity: 1;
  }

  .afx-shader-canvas[data-ready="false"] {
    transition: none;
  }

  .afx-background-scrim {
    background:
      linear-gradient(90deg, rgb(9 10 22 / 62%), transparent 78%),
      linear-gradient(180deg, rgb(9 10 22 / 8%), rgb(9 10 22 / 48%));
  }

  .afx-background-content {
    position: relative;
    z-index: 1;
    height: 100%;
  }

  .afx-surface {
    position: relative;
    isolation: isolate;
    border-radius: var(--af-radius, 1.25rem);
    border: 1px solid var(--border, rgb(139 92 246 / 20%));
    background-color: var(--surface, #11111f);
    color: var(--foreground, #f8fafc);
    box-shadow: 0 16px 48px -24px rgb(10 8 30 / 42%);
  }

  .afx-spotlight::before,
  .afx-tilt::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    pointer-events: none;
    background: radial-gradient(
      circle var(--afx-spotlight-radius, 320px) at var(--afx-pointer-x, 50%)
        var(--afx-pointer-y, 35%),
      color-mix(
          in srgb,
          var(--afx-spotlight-color, #8b5cf6)
            calc(var(--afx-spotlight-intensity, 0.2) * 100%),
          transparent
        )
        0%,
      transparent 75%
    );
    opacity: 0.65;
    transition: opacity 180ms ease;
  }

  .afx-spotlight[data-afx-pointer="active"]::before,
  .afx-tilt[data-afx-pointer="active"]::before {
    opacity: 1;
  }

  .afx-glow-border::before,
  .afx-glow-border::after {
    content: "";
    position: absolute;
    inset: -1px;
    border-radius: inherit;
    padding: var(--afx-border-width, 1px);
    pointer-events: none;
    background: conic-gradient(
      from var(--afx-orbit),
      var(--afx-color-a, #8b5cf6),
      var(--afx-color-b, #22d3ee) 28%,
      var(--afx-color-c, #34d399) 48%,
      transparent 63%,
      var(--afx-color-a, #8b5cf6) 84%,
      var(--afx-color-b, #22d3ee)
    );
    -webkit-mask:
      linear-gradient(#fff 0 0) content-box,
      linear-gradient(#fff 0 0);
    mask:
      linear-gradient(#fff 0 0) content-box,
      linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    animation: afx-border-orbit var(--afx-border-duration, 12s)
      steps(var(--afx-border-steps, 360), end) infinite;
    animation-play-state: paused;
  }

  .afx-glow-border::before {
    opacity: 0.9;
  }

  .afx-glow-border::after {
    inset: -3px;
    opacity: 0.32;
    filter: blur(5px);
  }

  .afx-glow-border[data-afx-motion="running"]::before,
  .afx-glow-border[data-afx-motion="running"]::after {
    animation-play-state: running;
  }

  .afx-tilt {
    transform: perspective(var(--afx-perspective, 900px))
      rotateX(var(--afx-rotate-x, 0deg)) rotateY(var(--afx-rotate-y, 0deg));
    transform-origin: center;
    transition: transform 180ms cubic-bezier(0.2, 0.7, 0.2, 1);
  }

  .afx-magnetic-button {
    position: relative;
    isolation: isolate;
    border: 1px solid rgb(255 255 255 / 18%);
    background: linear-gradient(
      120deg,
      color-mix(in srgb, var(--af-color-primary, #8b5cf6) 40%, #211938),
      #7044d8 58%,
      #3f59aa
    );
    color: #fff;
    box-shadow:
      inset 0 1px 0 rgb(255 255 255 / 16%),
      0 6px 24px -8px rgb(139 92 246 / 56%);
    transform: translate(
      var(--afx-magnetic-x, 0px),
      var(--afx-magnetic-y, 0px)
    );
    transition:
      transform 200ms cubic-bezier(0.2, 0.7, 0.2, 1),
      box-shadow 180ms ease;
    cursor: pointer;
  }

  .afx-magnetic-button:disabled,
  .afx-magnetic-button[aria-disabled="true"],
  .afx-magnetic-button[data-disabled] {
    opacity: 0.5;
    cursor: default;
    transform: none;
  }
}

/* Focus decoration is static and survives every motion preference. */
.afx-surface:focus-visible,
.afx-surface:has(:focus-visible),
.afx-magnetic-button:focus-visible {
  outline: 2px solid var(--ring, #22d3ee);
  outline-offset: 4px;
}

.afx-surface:focus-visible::before,
.afx-surface:has(:focus-visible)::before {
  opacity: 1;
}

.afx-tilt:focus-within,
.afx-magnetic-button:focus-within {
  transform: none;
}

@media (hover: none), (pointer: coarse) {
  .afx-tilt,
  .afx-magnetic-button {
    transform: none;
    transition: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .afx-shader-canvas {
    opacity: 0 !important;
    transition: none;
  }

  .afx-tilt,
  .afx-magnetic-button {
    transform: none;
  }

  .afx-tilt,
  .afx-magnetic-button,
  .afx-spotlight::before,
  .afx-tilt::before {
    transition: none;
  }

  .afx-glow-border::before,
  .afx-glow-border::after {
    animation: none;
  }
}

[data-shader-state="off"] .afx-shader-canvas,
.afx-shader-canvas[data-shader-state="off"] {
  opacity: 0 !important;
  transition: none;
}

.afx-tilt[data-afx-motion="paused"],
.afx-magnetic-button[data-afx-motion="paused"] {
  transform: none;
  transition: none;
}

.afx-spotlight[data-afx-motion="paused"]::before,
.afx-tilt[data-afx-motion="paused"]::before {
  transition: none;
}

.afx-glow-border[data-afx-motion="paused"]::before,
.afx-glow-border[data-afx-motion="paused"]::after {
  animation-play-state: paused;
}

@media (forced-colors: active) {
  .afx-background-field,
  .afx-shader-canvas,
  .afx-background-scrim,
  .afx-spotlight::before,
  .afx-tilt::before,
  .afx-glow-border::before,
  .afx-glow-border::after {
    display: none;
  }

  .afx-background,
  .afx-surface,
  .afx-magnetic-button {
    background: Canvas;
    color: CanvasText;
    border: 1px solid ButtonText;
    box-shadow: none;
  }

  .afx-surface:focus-visible,
  .afx-surface:has(:focus-visible),
  .afx-magnetic-button:focus-visible {
    outline-color: Highlight;
  }
}

"use client";

import { useRef } from "react";
